// Extract input data and build the full prompt
const input = $input.first().json;
const body = input.body || input;

const userMessage = body.message || '';
const conversationHistory = body.conversationHistory || [];
const userName = body.userName || null;
const userEmail = body.userEmail || null;
const leadData = body.leadData || {};
const timestamp = body.timestamp || new Date().toISOString();

// Build the system prompt
const systemPrompt = `You are an AI assistant for Aasani Systems, a workflow automation and AI consultancy.

# Your Identity & Role
- Represent Udy, founder of Aasani Systems (Austin, TX)
- Consultative approach, not pushy sales
- Data-driven but empathetic
- Expert at identifying operational inefficiencies

# About Aasani Systems
**Philosophy**: "Structure Before Intelligence"
- Build systematic foundations BEFORE implementing AI
- Process design and human-in-the-loop workflows

**Services & Pricing**:
- Foundation Assessment: $5,500 (2-week operational audit)
- System Build: Custom pricing
- Smart Systems: AI-powered workflows
- Ongoing Support: Retainer packages

**Target Clients**: 5-50 employee businesses

# Conversation Flow
1. Get their name conversationally
2. Discover their biggest operational pain point
3. Ask clarifying questions:
   - "How many tools are you juggling?"
   - "What's your team size?"
   - "What industry are you in?"
4. Calculate monthly cost of their chaos
5. Offer 15-min discovery call when qualified

# Cost Calculation Formulas

**Manual Data Entry**: Hours/week × 4.3 × $25 × team size
**Tool Chaos**: Each tool = $150-200/month per person
**Documentation Gap**: Extra onboarding weeks × 40 × hourly rate

# Calendar Trigger (show when ALL true):
- 3+ messages sent
- Clear pain point
- Cost > $3K/month acknowledged
- Interest in solutions shown

**Calendar**: https://cal.com/ayub-yousaf-c1ijnf/15min

# Response Rules
- 2-3 sentences max
- Conversational, not corporate
- Use their name once known
- Show math for cost calculations

# CRITICAL: JSON Response Format
Respond with ONLY valid JSON:

{
  "reply": "Your message here",
  "quickReplies": ["Option 1", "Option 2"],
  "showCostCard": false,
  "costAmount": 0,
  "showCalendar": false
}

Fields:
- reply: String, your response
- quickReplies: Array of 2-4 short options (or empty [])
- showCostCard: true only when you calculated their waste
- costAmount: Monthly cost in dollars
- showCalendar: true only when fully qualified`;

// Build messages array
const messages = [];

// Add conversation history
if (conversationHistory.length > 0) {
  for (const msg of conversationHistory) {
    messages.push({
      role: msg.role,
      content: msg.content
    });
  }
}

// Add current user message
messages.push({
  role: 'user',
  content: userMessage
});

// Build the full prompt for the LLM
const fullPrompt = systemPrompt + '\n\nConversation so far:\n' + 
  messages.map(m => `${m.role}: ${m.content}`).join('\n') +
  '\n\nRespond with valid JSON only:';

return [{
  json: {
    fullPrompt,
    userMessage,
    conversationHistory,
    userName,
    userEmail,
    leadData,
    timestamp,
    messageCount: conversationHistory.length + 1
  }
}];

// Parse the LLM response and extract JSON
const input = $input.first().json;
const prevData = $('Code - Build Prompt').first().json;

// Get the response text
let responseText = input.response?.text || input.text || input.output || '';

// Try to extract JSON from the response
let parsedResponse;
try {
  // Try to find JSON in the response
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsedResponse = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found in response');
  }
} catch (e) {
  // Fallback response
  parsedResponse = {
    reply: responseText.substring(0, 500) || "I'm here to help! What operational challenges are you facing?",
    quickReplies: ["Tool integration", "Manual data entry", "Team coordination"],
    showCostCard: false,
    costAmount: 0,
    showCalendar: false
  };
}

// Normalize fields
parsedResponse.reply = parsedResponse.reply || "How can I help you today?";
parsedResponse.quickReplies = Array.isArray(parsedResponse.quickReplies) ? parsedResponse.quickReplies.slice(0, 4) : [];
parsedResponse.showCostCard = Boolean(parsedResponse.showCostCard);
parsedResponse.showCalendar = Boolean(parsedResponse.showCalendar);
parsedResponse.costAmount = Number(parsedResponse.costAmount) || 0;

// Determine qualification
const isQualified = parsedResponse.showCalendar || 
                   parsedResponse.costAmount > 3000 ||
                   (prevData.messageCount > 4 && parsedResponse.showCostCard);

return [{
  json: {
    ...parsedResponse,
    userName: prevData.userName,
    userEmail: prevData.userEmail,
    leadData: {
      ...prevData.leadData,
      lastCalculatedCost: parsedResponse.costAmount
    },
    isQualified,
    timestamp: prevData.timestamp,
    messageCount: prevData.messageCount
  }
}];
